503	/**
504	 * Build Commander argv from a BatchCommand and its CommandMeta.
505	 *
506	 * Translates { command: "inbox add", args: { content: "hello", tag: ["a","b"] } }
507	 * into ["inbox", "add", "hello", "--tag", "a", "--tag", "b"]
508	 *
509	 * Positional args are emitted in Commander definition order (not JSON key order)
510	 * to ensure correct argument mapping regardless of how the JSON was serialized.
511	 */
512	/**
513	 * Serialize a value for CLI argv. Plain objects are JSON-stringified
514	 * so that flags like --data receive valid JSON instead of "[object Object]".
515	 */
516	function toArgString(value: unknown): string {
517	  if (typeof value === "object" && value !== null && !Array.isArray(value)) {
518	    return JSON.stringify(value);
519	  }
520	  return String(value);
521	}
522	
523	function normalizePriorityAlias(value: unknown): unknown {
524	  if (Array.isArray(value)) {
525	    return value.map((v) => normalizePriorityAlias(v));
526	  }
527	  if (typeof value !== "string") {
528	    return value;
529	  }
530	  const match = value.match(/^[Pp]([1-5])$/);
531	  return match ? match[1] : value;
532	}
533	
534	function isNumericPriorityOption(
535	  option: { name: string; flags: string; description?: string } | undefined,
536	): boolean {
537	  if (!option || normalizeArgKey(option.name) !== "priority") {
538	    return false;
539	  }
540	  const hasNumericPlaceholder = /<n(?:umber)?>/.test(option.flags);
541	  const hasNumericRangeHint = /\b1-5\b/.test(option.description ?? "");
542	  return hasNumericPlaceholder || hasNumericRangeHint;
543	}
544	
545	function isNumericPriorityArgument(arg: { name: string; description?: string }): boolean {
546	  if (normalizeArgKey(arg.name) !== "priority") {
547	    return false;
548	  }
549	  return /\b1-5\b/.test(arg.description ?? "");
550	}
