552	export function buildCommandArgv(cmd: BatchCommand, cmdMeta: CommandMeta): string[] {
553	  const argv: string[] = [...cmd.command.trim().split(/\s+/)];
554	  const consumedKeys = new Set<string>();
555	
556	  // Build sets for classification
557	  const positionalDefs = cmdMeta.arguments; // ordered by Commander definition
558	  const positionalCanonicalNameSet = new Set<string>();
559	  for (const arg of positionalDefs) {
560	    positionalCanonicalNameSet.add(normalizeArgKey(arg.name));
561	  }
562	
563	  const optionMap = new Map<string, {
564	    flags: string;
565	    variadic: boolean;
566	    name: string;
567	    description: string;
568	  }>();
569	  for (const opt of cmdMeta.options) {
570	    const name = extractOptionName(opt.flags);
571	    if (name) {
572	      optionMap.set(normalizeArgKey(name), {
573	        flags: opt.flags,
574	        variadic: opt.variadic,
575	        name,
576	        description: opt.description,
577	      });
578	    }
579	  }
580	
581	  // Phase 1: Emit positional args in Commander definition order
582	  for (const argDef of positionalDefs) {
583	    const canonicalName = normalizeArgKey(argDef.name);
584	    const matchedKey = Object.keys(cmd.args).find(
585	      (k) => normalizeArgKey(k) === canonicalName,
586	    );
587	    const value = matchedKey ? cmd.args[matchedKey] : undefined;
588	    if (value === undefined) continue;
589	    consumedKeys.add(matchedKey!);
590	
591	    const normalizedValue = isNumericPriorityArgument(argDef)
592	      ? normalizePriorityAlias(value)
593	      : value;
594	
595	    if (Array.isArray(normalizedValue)) {
596	      for (const v of normalizedValue) argv.push(toArgString(v));
597	    } else {
598	      argv.push(toArgString(normalizedValue));
599	    }
600	  }
601	
602	  // Phase 2: Emit options from remaining keys
603	  for (const [key, value] of Object.entries(cmd.args)) {
604	    if (consumedKeys.has(key)) {
605	      continue;
606	    }
607	
608	    const canonicalKey = normalizeArgKey(key);
609	    // Skip positional args (already emitted)
610	    if (positionalCanonicalNameSet.has(canonicalKey)) {
611	      continue;
612	    }
613	
614	    const knownOption = optionMap.get(canonicalKey);
615	    const flagName = `--${knownOption?.name ?? canonicalKey}`;
616	    const normalizedValue = isNumericPriorityOption(knownOption)
617	      ? normalizePriorityAlias(value)
618	      : value;
619	
620	    if (typeof normalizedValue === "boolean") {
621	      if (normalizedValue) {
622	        argv.push(flagName);
623	      }
624	      // false booleans: omit (Commander treats absence as false)
625	    } else if (Array.isArray(normalizedValue)) {
626	      // Variadic or repeated options
627	      for (const v of normalizedValue) {
628	        argv.push(flagName, toArgString(v));
629	      }
630	    } else if (normalizedValue !== null && normalizedValue !== undefined) {
631	      argv.push(flagName, toArgString(normalizedValue));
632	    }
633	  }
634	
635	  return argv;
636	}
